INSERT INTO `scans` VALUES ('2b39f532-0362-4e0e-9959-b7512b8fcb57','fdb5ec6a-5aa2-4872-bc22-7da2d5a16aee','standard','completed',100,'2025-09-04 17:29:42','2025-09-04 17:29:43',NULL,'{\"url\": \"https://google.com\", \"score\": 60, \"preview\": {\"aiVisibility\": 55, \"contentQuality\": 63, \"technicalHealth\": 61}, \"summary\": {\"status\": \"warning\", \"message\": \"google.com 存在一些影響 AI 可見度的問題需要改善。\", \"keyIssues\": [\"缺少 viewport meta 標籤\", \"標題過短 (6 字元)\", \"缺少 Meta 描述標籤\", \"Performance分數: 65/100, LCP: 3.5s\"]}, \"aiVisibility\": {\"items\": [{\"name\": \"Schema 標記\", \"score\": 60, \"detail\": \"發現 1 個結構化資料\", \"status\": \"warning\", \"recommendation\": \"增加更多相關的結構化資料標記\"}, {\"name\": \"社群媒體標記\", \"score\": 40, \"detail\": \"缺少 Open Graph 和 Twitter 標記\", \"status\": \"warning\", \"recommendation\": \"加入 Open Graph 和 Twitter Card 標記\"}, {\"name\": \"FAQ 內容\", \"score\": 50, \"detail\": \"未發現 FAQ 或問答內容\", \"status\": \"warning\", \"recommendation\": \"加入常見問題解答以提升 AI 查詢回應\"}, {\"name\": \"內容可讀性\", \"score\": 70, \"detail\": \"句子過短 (平均 5 字/句)\", \"status\": \"warning\", \"recommendation\": \"適度增加句子內容深度\"}], \"score\": 55, \"weight\": 30}, \"contentQuality\": {\"items\": [{\"name\": \"標題結構\", \"score\": 20, \"detail\": \"缺少 H1 主標題\", \"status\": \"critical\", \"recommendation\": \"每個頁面都應該有一個 H1 標題\"}, {\"name\": \"內容長度\", \"score\": 30, \"detail\": \"內容過短 (約 13 字)\", \"status\": \"critical\", \"recommendation\": \"建議內容長度至少 300 字以上\"}, {\"name\": \"圖片優化\", \"score\": 100, \"detail\": \"所有圖片都有 Alt 文字 (1/1)\", \"status\": \"good\"}, {\"name\": \"內部連結\", \"score\": 100, \"detail\": \"有適量的連結 (30 個)\", \"status\": \"good\"}], \"score\": 63, \"weight\": 30}, \"upgradeReasons\": [\"獲得 30+ 項技術指標詳細分析\", \"查看具體競爭對手表現比較\", \"獲得個人化優化執行計劃\", \"追蹤改善進度和成效監控\"], \"technicalHealth\": {\"items\": [{\"name\": \"robots.txt 配置\", \"score\": 100, \"detail\": \"已允許搜尋引擎爬取\", \"status\": \"good\"}, {\"name\": \"HTTPS 安全連線\", \"score\": 100, \"detail\": \"使用安全的 HTTPS 連線\", \"status\": \"go